The optional *maxsplit* argument limits the number of splits performed:

    >>> list(sliced((1, 2, 3, 4, 5, 6), 3, maxsplit=1))
    [(1, 2, 3)]

"""
if maxsplit is None:
    return takewhile(len, (seq[i : i + n] for i in count(0, n)))
else:
    return islice(takewhile(len, (seq[i : i + n] for i in count(0, n))), maxsplit)

